'use client';

import { api } from '@/lib/api';

/**
 * Official ORYX brand lockup, or a company's uploaded logo.
 *
 * The owner-supplied artwork is a single raster lockup (icon + wordmark), so it
 * is used as-is rather than re-typeset. Two colourways are shipped because the
 * source JPEG has no alpha channel: `-on-dark` knocks the navy ink out to white
 * for navy surfaces, `-on-light` keeps the original navy/gold for light ones.
 * Both are generated by `.run/gen-brand.cjs` from `docs/assets/logo.png.jpeg`.
 *
 * When a tenant has uploaded a logo (`assetId`) that image is used instead, in
 * both colourways: a company supplies one mark and expects to see it, so the
 * shell does not second-guess which theme it suits. With no upload the packaged
 * ORYX lockup is used and its colourways are swapped by CSS on `data-theme`, so
 * the correct one appears on first paint without a JS theme read.
 */

const RATIO = 1404 / 320;

export function BrandLogo({
  height = 30,
  className,
  assetId = null,
  alt = 'ORYX',
}: {
  height?: number;
  className?: string;
  /** A `CmsMediaAsset` id for a tenant logo; `null` uses the packaged lockup. */
  assetId?: string | null;
  alt?: string;
}) {
  const width = Math.round(height * RATIO);

  if (assetId) {
    return (
      <span
        className={`oryx-brand-logo oryx-brand-logo--custom${className ? ` ${className}` : ''}`}
        style={{ height, width }}
      >
        {/* Served by the public media endpoint, so it renders without a token
            and caches immutably. `object-fit: contain` keeps an arbitrary
            tenant logo's aspect ratio inside the lockup's slot. */}
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={api.mediaFileUrl(assetId, 'card')}
          alt={alt}
          height={height}
          width={width}
          decoding="async"
          style={{ width: '100%', height: '100%', objectFit: 'contain' }}
        />
      </span>
    );
  }

  return (
    <span
      className={`oryx-brand-logo${className ? ` ${className}` : ''}`}
      style={{ height, width }}
    >
      {/* The artwork is a single raster lockup, so `next/image`'s loader buys
          nothing here; both colourways are pre-sized and served as static PNGs. */}
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src="/brand/oryx-logo-on-dark.png"
        alt={alt}
        className="oryx-brand-logo__on-dark"
        height={height}
        width={width}
        decoding="async"
      />
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src="/brand/oryx-logo-on-light.png"
        alt=""
        aria-hidden="true"
        className="oryx-brand-logo__on-light"
        height={height}
        width={width}
        decoding="async"
      />
    </span>
  );
}

export { RATIO as BRAND_LOGO_RATIO };
